/* Customer guidance derives from current records; no new persisted state or permissions. */
(function(){
'use strict';
const last=d=>d?.versions?.at(-1);
function reviewQueue(data,clientId){const projects=new Map(data.projects.filter(p=>p.clientId===clientId).map(p=>[p.id,p]));return data.deliverables.flatMap(d=>{const version=last(d),project=projects.get(d.projectId);return project&&version?.status==='pending'?[{deliverable:d,version,project}]:[];});}
function nextActions(data){return data.projects.filter(p=>!data.workspace.projectMeta?.[p.id]?.archived).flatMap(project=>{const work=data.deliverables.filter(d=>d.projectId===project.id),changed=work.filter(d=>last(d)?.status==='changes'),pending=work.filter(d=>last(d)?.status==='pending');return !work.length?[{project,kind:'empty',count:0}]:changed.length?[{project,kind:'changes',count:changed.length}]:pending.length?[{project,kind:'pending',count:pending.length}]:[];});}
function setupProgress(data){const projects=data.projects.filter(p=>data.clients.some(c=>c.id===p.clientId)),work=data.deliverables.filter(d=>projects.some(p=>p.id===d.projectId)&&d.versions?.length);return [data.clients.length>0,projects.length>0,work.length>0,data.approvals.some(a=>work.some(d=>d.id===a.deliverableId&&d.versions.some(v=>v.id===a.versionId)))];}
function currentFiles(data,d){return data.workspace.assets.filter(a=>a.deliverableId===d.id&&a.versionId===last(d)?.id);}
const model={reviewQueue,nextActions,setupProgress,currentFiles};
if(typeof module!=='undefined'&&module.exports)module.exports=model;
if(typeof window==='undefined'||!window.PF)return;
const PF=window.PF,E=PF.e,main=document.querySelector('#main');PF.customerExperience=model;
let reviewOnly=false,context='';
const agency=()=>!PF.shared?.active||PF.shared.role==='agency';
const coreCard=deliverableCard;
deliverableCard=function(d,isPortal){const v=last(d),files=currentFiles(PF.db,d);let html=coreCard(d,isPortal);if(!isPortal)html=html.replace('<details class="space-top" data-pf-comparison=', '<p class="meta">Attach PNG, JPEG, WEBP, PDF or plain text, up to 1 MiB per file. Attachments can be added before a review decision.</p><details class="space-top" data-pf-comparison=');if(files.length){html=html.replace('<span class="meta">Text deliverable — review the notes above.</span>','');const evidence=`<section class="pf-decision-files" aria-label="Current version files"><b>Files for version ${E(v.number)}</b><ul>${files.map(a=>`<li><span>${E(a.name)}</span>${PF.button('Download file','pf-file-download',a.id)}</li>`).join('')}</ul></section>`;html=html.replace('<div class="actions">',evidence+'<div class="actions">');}if(isPortal){const text=PF.shared?.active?(PF.shared.role==='client'?'Your decision is recorded for this version. After a decision, the agency must submit a new version for another review.':'Client layout preview: only the invited client account can record a decision.'):'Preview only: decisions here are saved in this browser and do not contact a client.';html=html.replace('<div class="actions">',`<p class="meta pf-decision-note">${E(text)}</p><div class="actions">`);}return `<div class="pf-review-item" data-pf-review-id="${E(d.id)}" data-pf-review-version="${E(v.id)}" data-pf-review-status="${E(v.status)}" tabindex="-1">${html}</div>`;};
function inviteButton(clientId){return PF.shared?.active&&PF.shared.role==='agency'?`<button type="button" data-pf-invite-client="${E(clientId)}">Create invitation link</button>`:PF.button('Preview client view','open-portal',clientId);}
function guidance(){const data=PF.db,progress=setupProgress(data),project=data.projects.find(p=>!PF.w.projectMeta[p.id]?.archived),rows=nextActions(data),pending=data.projects.find(p=>!PF.w.projectMeta[p.id]?.archived&&data.deliverables.some(d=>d.projectId===p.id&&last(d)?.status==='pending')),revision=rows.find(row=>row.kind==='changes');const setup=`<section class="card pf-customer-guidance" aria-labelledby="pf-first-review"><div class="section-heading"><h2 id="pf-first-review">Your first review, step by step</h2><span class="badge">${progress.filter(Boolean).length} of 4 complete</span></div><ol class="pf-setup-steps">${['Add a client','Create their project','Add work to review','Receive a client decision'].map((text,i)=>`<li class="${progress[i]?'pf-step-done':''}"><span aria-hidden="true">${progress[i]?'✓':i+1}</span>${text}${progress[i]?'<small>Complete</small>':''}</li>`).join('')}</ol><p class="meta">${PF.shared?.active?'Create an invitation link and share it with your client to collect their decision. Invitation links do not send an email.':'You are using a local preview. Try the review flow here; real invitations require a shared account.'}</p><div class="actions">${!progress[0]?PF.button('Add client','new-client','',true):!progress[1]?PF.button('Create a project','new-project',data.clients[0].id,true):!progress[2]&&project?PF.button('Add work to review','new-deliverable',project.id,true):!progress[3]&&pending?inviteButton(pending.clientId):!progress[3]&&revision?PF.button('Open feedback','project',revision.project.id,true):!progress[3]&&project?PF.button('Add work to review','new-deliverable',project.id,true):!progress[3]?PF.button('Create a project','new-project',data.clients[0]?.id||'',true):''}</div></section>`;return `${progress.every(Boolean)?'':setup}${rows.length||progress.every(Boolean)?'<section class="card pf-customer-guidance"><h2>What needs your attention</h2>':''}${rows.map(({project:p,kind,count})=>`<div class="pf-next-action"><div><b>${E(p.name)}</b><p>${kind==='empty'?'Add the first piece of work for your client to review.':kind==='changes'?`${count} ${count===1?'item needs':'items need'} a revision. Open the feedback, then submit a new version.`:`${count} ${count===1?'item is':'items are'} awaiting your client’s decision.`}</p></div><div class="actions">${PF.button(kind==='empty'?'Add work':'Open project',kind==='empty'?'new-deliverable':'project',p.id)}${kind==='pending'?inviteButton(p.clientId):''}</div></div>`).join('')||(progress.every(Boolean)?'<p>No active review actions right now. Your recorded decisions remain in Approval history.</p>':'')}${rows.length||progress.every(Boolean)?'</section>':''}`;}
function queue(){const c=PF.client(portalClient);if(!c)return '';const items=reviewQueue(PF.db,c.id);return `<section id="pf-review-queue" class="card pf-customer-guidance" aria-labelledby="pf-review-queue-title"><div class="section-heading"><h2 id="pf-review-queue-title">Needs your review</h2><span class="badge">${items.length}</span></div><p>${items.length?'Start with a pending version below. Read the work and files before recording your decision.':'You’re all caught up. Your agency will share new work here when it is ready.'}</p>${items.map(({deliverable:d,version:v,project:p})=>`<div class="pf-next-action"><div><b>${E(d.title)}</b><p class="meta">${E(p.name)} · Version ${E(v.number)}</p></div><button type="button" data-pf-review-jump="${E(d.id)}" data-pf-review-target-version="${E(v.id)}">Review version ${E(v.number)}</button></div>`).join('')}<div class="pf-review-filters" role="group" aria-label="Filter review work"><button type="button" data-pf-review-filter="all" aria-pressed="${!reviewOnly}">All work</button><button type="button" data-pf-review-filter="pending" aria-pressed="${reviewOnly}">Awaiting review (${items.length})</button></div><p class="meta">This filter affects review items only. Messages, requests and onboarding stay available below.</p></section>`;}
function filterReviews(){for(const item of main.querySelectorAll('.pf-review-item'))item.hidden=reviewOnly&&item.dataset.pfReviewStatus!=='pending';for(const b of main.querySelectorAll('[data-pf-review-filter]'))b.setAttribute('aria-pressed',String((b.dataset.pfReviewFilter==='pending')===reviewOnly));}
function filesHelp(){const select=main.querySelector('#pf-files-client');if(!select)return;const selected=select.value,items=PF.w.assets.filter(a=>!selected||PF.project(a.projectId)?.clientId===selected);if(items.length)return;const project=PF.db.projects.find(p=>(!selected||p.clientId===selected)&&!PF.w.projectMeta[p.id]?.archived);let action='';if(agency()){if(project)action=PF.button('Open project to attach files','project',project.id);else if(PF.db.clients.length)action=PF.button('Create a project','new-project',selected||PF.db.clients[0].id);else action=PF.button('Add your first client','new-client');}const section=document.createElement('section');section.className='card pf-customer-guidance';section.innerHTML=`<h2>${selected?'No files for this client yet':'Your reviewed files, in one place'}</h2><p>Files are attached to a deliverable’s current version inside its project. Open a deliverable, then choose “Attach to current version” before a decision is recorded.</p><p class="meta">PNG, JPEG, WEBP, PDF and plain text · maximum 1 MiB per file. Already reviewed versions keep their original snapshots.</p><div class="actions">${action}${selected?'<button type="button" data-pf-clear-files>Show files from all clients</button>':''}</div>`;main.append(section);}
function sync(){if(PF.shared?.active&&!PF.shared.role)return;const nextContext=String(PF.shared?.active)+'|'+(PF.shared?.role||'preview')+'|'+portalClient;if(context!==nextContext){reviewOnly=false;context=nextContext;}if(view==='dashboard'&&agency()){const box=document.createElement('div');box.innerHTML=guidance();const first=main.querySelector('.heading');if(first)first.after(box);else main.prepend(box);}if(view==='portal'){const box=document.createElement('div');box.innerHTML=queue();const hero=main.querySelector('.portal-hero');if(hero)hero.after(box);else main.prepend(box);filterReviews();}if(view==='files')filesHelp();}
const previousRender=render;render=function(){previousRender();sync();};PF.render=()=>render();
document.addEventListener('click',event=>{const jump=event.target.closest('[data-pf-review-jump]');if(jump&&view==='portal'){const item=Array.from(main.querySelectorAll('.pf-review-item')).find(el=>el.dataset.pfReviewId===jump.dataset.pfReviewJump&&el.dataset.pfReviewVersion===jump.dataset.pfReviewTargetVersion);if(item){item.hidden=false;item.scrollIntoView({block:'start',behavior:'instant'});item.focus({preventScroll:true});}return;}const filter=event.target.closest('[data-pf-review-filter]');if(filter&&view==='portal'){reviewOnly=filter.dataset.pfReviewFilter==='pending';filterReviews();return;}const clear=event.target.closest('[data-pf-clear-files]');if(clear&&view==='files'){const select=main.querySelector('#pf-files-client');if(select){select.value='';select.dispatchEvent(new Event('change',{bubbles:true}));}return;}const invite=event.target.closest('[data-pf-invite-client]');if(invite&&PF.shared?.active&&PF.shared.role==='agency'&&PF.client(invite.dataset.pfInviteClient)){document.querySelector('#pf-invite')?.click();const select=document.querySelector('#modal [name="clientId"]');if(select){select.value=invite.dataset.pfInviteClient;document.querySelector('#modal').dispatchEvent(new Event('pf-form-prefill'));}}});
sync();
})();
